import {sensitivityTornado,contributionSensitivity} from './sensitivity-visuals.js?v=2.5.2';
import {SENSITIVITY_PARAMETERS,sensitivityParameters} from './sensitivity.js?v=2.5.2';
import {operatingPointLabel,orderedOperatingPoints} from './result-view.js?v=2.5.2';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=v=>Number.isFinite(v)?Number(v.toPrecision(5)).toString():'—';
export function diagnosticTable(rows){const items=orderedOperatingPoints(rows).flatMap(r=>r.devices.flatMap(d=>(d.diagnostics||[]).map(q=>({r,d,q}))));if(!items.length)return '<p class="caption">No curve-query diagnostics recorded.</p>';return `<div class="table-wrap"><table><thead><tr><th>Operating point / component</th><th>Characteristic / condition</th><th>Requested input range</th><th>Reference input range</th><th>Requested dependencies</th><th>Queries affected</th></tr></thead><tbody>${items.map(({r,d,q})=>`<tr><td>${esc(operatingPointLabel(r))}<br>${esc(d.instanceName+' / '+d.part)}</td><td>${esc(q.characteristic)}<br>${esc(q.message)}</td><td>${q.requestedRange.map(n).join(' … ')} ${esc(q.given)}</td><td>${q.referenceRange?.map(n).join(' … ')||'—'} ${esc(q.given)}</td><td>${Object.entries(q.dependencies).map(([k,v])=>esc(k)+'='+v.map(n).join(' … ')).join('<br>')}</td><td>${q.count}</td></tr>`).join('')}</tbody></table></div>`;}
export function sensitivityResults(data){if(!data)return '';const improving=data.scenarios.filter(s=>s.valid&&s.lossChange<0).sort((a,b)=>a.lossChange-b.lossChange),best=improving[0];return `<h3>Sensitivity comparison</h3><label>Comparison basis<select id="tornadoMode"><option value="steps">Chosen perturbations</option><option value="normalized">Normalised percent sensitivity</option></select></label><div id="tornadoChart">${sensitivityTornado(data)}</div>${contributionSensitivity(data)}${best?`<p><b>Largest predicted reduction in this sweep:</b> ${esc(best.label)} ${n(best.change)} ${esc(best.unit)} → mean total loss ${n(best.lossChange)}%. Review model notes before treating this as a design recommendation.</p>`:''}<p>Baseline mean total loss: <b>${n(data.baseline.loss)} W</b> · ${data.operatingPoints} operating points · combination ${data.combination}</p><div class="table-wrap"><table><thead><tr><th>Parameter</th><th>Requested step</th><th>Actual change</th><th>Before → after</th><th>Mean total loss [W]</th><th>Loss change [%]</th><th>Loss change [W]</th><th>Efficiency change [percentage points]</th><th>Loss % / parameter %</th><th>Coverage</th></tr></thead><tbody>${data.scenarios.map(s=>`<tr><td>${esc(s.label)}</td><td>${s.requested?esc('±'+s.requested.value+' '+s.requested.unit):'Legacy setting'}</td><td>${n(s.change)} ${esc(s.unit||'')}</td><td>${n(s.before)} → ${n(s.after)}</td><td>${n(s.meanLoss)}</td><td style="color:${s.lossChange<0?'var(--accent)':'inherit'}">${n(s.lossChange)}</td><td>${n(s.lossDelta)}</td><td>${n(s.efficiencyDelta)}</td><td>${n(s.elasticity)}</td><td>${s.valid?'Computed':esc(s.errors?.join('; '))}${s.warnings?.length?`<details><summary>${s.warnings.length} model notes</summary><ul>${s.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></details>`:''}</td></tr>`).join('')}</tbody></table></div><p class="caption">${esc(data.assumption)}</p>`;}
export function sensitivityControls(project,result,combination,data){const row=result.rows.find(r=>r.combination===combination&&r.valid);if(!row)return '<p>Sensitivity requires a valid combination.</p>';const settings=project.sensitivitySettings||{},selection=row.devices.map(d=>({id:d.instanceId+':'+d.candidateId,label:d.instanceName+' / '+d.part})),target=selection.find(v=>v.id===(settings.target||data?.instanceId+':'+data?.candidateId))||selection[0],inst=project.instances.find(i=>i.id===target.id.split(':')[0]),candidate=inst.candidates.find(c=>c.id===target.id.split(':')[1]),parameters=sensitivityParameters(inst,candidate);return `<div class="form-grid"><label>Target component<select id="sensitivityTarget">${selection.map(v=>`<option value="${v.id}" ${v.id===target.id?'selected':''}>${esc(v.label)}</option>`).join('')}</select></label><label>Operating points<select id="sensitivityWave"><option value="">All operating points</option>${orderedOperatingPoints(result.rows.filter(r=>r.combination===combination)).map(r=>`<option value="${r.waveformId}" ${r.waveformId===settings.waveformId?'selected':''}>${esc(operatingPointLabel(r))}</option>`).join('')}</select></label></div><div class="sensitivity-parameters">${Object.entries(parameters).map(([key,label])=>`<div class="form-grid"><label class="check"><input type="checkbox" data-sensitivity="${key}" ${(settings.parameters?settings.parameters.includes(key):data?data.scenarios.some(s=>s.parameter===key):!['series','parallel'].includes(key))?'checked':''}>${esc(label)}</label><label>${esc(label)} perturbation<input data-perturbation="${key}" type="number" min="0.001" step="any" value="${(settings.perturbations?.[key]??data?.perturbations?.[key])?.value??(key==='temperature'?5:['parallel','series'].includes(key)?1:2)}"></label><label>${esc(label)} step unit<select data-perturbation-unit="${key}"><option value="%" ${((settings.perturbations?.[key]??data?.perturbations?.[key])?.unit??(['temperature','parallel','series'].includes(key)?'absolute':'%'))==='%'?'selected':''}>%</option>${key==='temperature'?`<option value="°C" ${((settings.perturbations?.[key]??data?.perturbations?.[key])?.unit??'°C')==='°C'?'selected':''}>°C</option>`:['parallel','series'].includes(key)?`<option value="devices" ${((settings.perturbations?.[key]??data?.perturbations?.[key])?.unit??'devices')==='devices'?'selected':''}>devices</option>`:''}</select></label></div>`).join('')}</div><p class="caption">Each selected parameter is varied down and up, one at a time. Each parameter has its own step and unit. Temperature percentages use absolute Kelvin temperature; °C steps are also available. Series and parallel percentages are rounded to a whole-device step; too-small steps are flagged, not silently changed. Series changes per-device voltage and device count; parallel changes per-device current and device count. Imported waveforms and frequency stay fixed. Fixed/unrepresented dependencies may give zero response. Gate-on Vgs requires a logic gate waveform.</p><div class="toolbar"><button class="primary" id="runSensitivity">Run sensitivity</button>${data?'<button class="ghost" id="downloadSensitivity">↓ Sensitivity JSON</button>':''}</div>${sensitivityResults(data)}`;}
export function selectReportResults(results,selection){const combo=new Set(selection.combinations),waves=new Set(selection.waveformIds),rows=orderedOperatingPoints(results.rows.filter(r=>combo.has(r.combination)&&waves.has(r.waveformId)));if(!rows.length)throw Error('Select at least one combination and operating point');const ranking=results.ranking.filter(r=>combo.has(r.combination)).map(r=>{const points=rows.filter(p=>p.combination===r.combination),valid=points.length>0&&points.every(p=>p.valid);return {...r,points:points.length,valid,meanLoss:valid?points.reduce((s,p)=>s+p.totalLoss,0)/points.length:null,meanEfficiency:valid?points.reduce((s,p)=>s+p.efficiency,0)/points.length:null,worstEfficiency:valid?Math.min(...points.map(p=>p.efficiency)):null};});const best=[...ranking].filter(r=>r.valid).sort((a,b)=>b.meanEfficiency-a.meanEfficiency||a.meanLoss-b.meanLoss)[0]||null;return {...results,rows,ranking,best};}
